for (const item of items) {
  if (item.binary && item.binary['data']) {
    const fileName = item.binary['data'].fileName || '';
    const lowerName = fileName.toLowerCase();

    if (lowerName.endsWith('.png')) {
      item.binary['data'].mimeType = 'image/png';
    } else if (lowerName.endsWith('.jpg') || lowerName.endsWith('.jpeg')) {
      item.binary['data'].mimeType = 'image/jpeg';
    } else if (lowerName.endsWith('.webp')) {
      item.binary['data'].mimeType = 'image/webp';
    }
  }
}
return items;

const supportedExtensions = [
  '.jpg', '.jpeg', '.png', '.webp',
  '.pdf',
  '.doc', '.docx',
  '.xls', '.xlsx',
  '.json', '.xml', '.csv'
];

const supportedMimeTypes = [
  'image/jpeg',
  'image/png',
  'image/webp',
  'application/pdf',
  'application/msword',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  'application/vnd.ms-excel',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',

  // JSON
  'application/json',
  'text/json',

  // XML
  'application/xml',
  'text/xml',

  // CSV
  'text/csv',
  'application/csv',
  'text/plain' // some systems mislabel CSV as plain text
];

return $input.all().map(item => {
  const fileName = item.binary?.data?.fileName || '';
  const mimeType = item.binary?.data?.mimeType || '';

  const lowerName = fileName.toLowerCase();

  const isExtensionSupported = supportedExtensions.some(ext =>
    lowerName.endsWith(ext)
  );

  const isMimeSupported = supportedMimeTypes.includes(mimeType);

  if (!isExtensionSupported && !isMimeSupported) {
    return {
      json: {
        is_supported: false,
        reason: "unsupported_file_type",
        fileName: fileName || "Unknown",
        mimeType: mimeType || "Unknown"
      }
    };
  }

  return {
    ...item,
    json: {
      ...(item.json || {}),
      is_supported: true,
      reason: "supported_file_type",
      fileName,
      mimeType
    }
  };
});

const results = [];
for (const item of $input.all()) {
const fileName = item.json?.fileName || item.json?.message?.document?.file_name || '';
const ext = fileName.toLowerCase().split('.').pop();

let type = 'unknown';
if (['jpg', 'jpeg', 'png', 'webp'].includes(ext)) {
type = 'image';
} else if (['pdf'].includes(ext)) {
type = 'pdf';
} else if (['doc', 'docx'].includes(ext)) {
type = 'word document';
} else if (['xls', 'xlsx'].includes(ext)) {
type = 'spreadsheet';
} else if (['json'].includes(ext)) {
type = 'json';
} else if (['xml'].includes(ext)) {
type = 'xml file'
}
item.json.fileTypeCategory = type;
results.push(item);
}
return results;

return items.map(item => {
  let output = item.json;

  // If input is a string, try to parse it as JSON
  if (typeof output === "string") {
    try {
      output = JSON.parse(output);
    } catch (e) {
      output = { value: output };
    }
  }

  // If input is a number / boolean / null → wrap it
  if (
    typeof output === "number" ||
    typeof output === "boolean" ||
    output === null
  ) {
    output = { value: output };
  }

  // If input is an array → wrap it
  if (Array.isArray(output)) {
    output = { data: output };
  }

  // If binary data exists → convert to base64 JSON
  if (item.binary) {
    output = {
      binary: Object.fromEntries(
        Object.entries(item.binary).map(([key, file]) => [
          key,
          {
            fileName: file.fileName,
            mimeType: file.mimeType,
            data: file.data
          }
        ])
      )
    };
  }

  return { json: output };
});
